          "anyOf": [
           {
            "anyOf": [
             {
              "type": "string",
              "maxLength": 1024
             },
             {
              "maxItems": 32,
              "type": "array",
              "items": {
               "type": "string",
               "maxLength": 128
              }
             }
            ]
           },
           {
            "type": "null"
           }
          ]
